def write_new_file(relative: str, encoded: str) -> None:
    path = ROOT / relative
    content = base64.b64decode(encoded).decode("utf-8")
    if path.exists():
        existing = path.read_text(encoding="utf-8")
        if existing != content:
            raise SystemExit(
                f"Refusing to overwrite an existing different Day 12 file: {relative}"
            )
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def patch_settings() -> None:
    path = ROOT / "apps/api/endoora_api/settings/base.py"
    text = path.read_text(encoding="utf-8")
    if '"taxonomy"' in text:
        return

    anchors = ['    "audit.apps.AuditConfig",\n', '    "audit",\n', '    "core",\n', '    "teachers",\n', '    "profiles",\n']
    for anchor in anchors:
        if anchor in text:
            text = text.replace(anchor, anchor + '    "taxonomy",\n', 1)
            path.write_text(text, encoding="utf-8")
            return

    raise SystemExit(
        "Could not find a safe INSTALLED_APPS anchor in apps/api/endoora_api/settings/base.py. "
        "No URL patch was attempted."
    )


def patch_urls() -> None:
    path = ROOT / "apps/api/endoora_api/urls.py"
    text = path.read_text(encoding="utf-8")
    route = '    path("api/taxonomy/", include("taxonomy.urls")),\n'
    if route in text:
        return

    close_index = text.rfind("]")
    if close_index == -1:
        raise SystemExit("Could not locate urlpatterns closing bracket safely.")

    text = text[:close_index] + route + text[close_index:]
    path.write_text(text, encoding="utf-8")


def append_once(relative: str, marker: str, note: str) -> None:
    path = ROOT / relative
    if not path.is_file():
        return
    text = path.read_text(encoding="utf-8")
    if marker in text:
        return
    path.write_text(text.rstrip() + "\n\n" + note.strip() + "\n", encoding="utf-8")


def main() -> None:
    for relative, encoded in PAYLOAD.items():
        write_new_file(relative, encoded)

    patch_settings()
    patch_urls()

